---@param params_ table @ { height : number, radius : number }
function VCam3rdPersonFollowParams:__init( params_ )
    assert( type(params_) == "table" and type(params_.height) == "number" and type(params_.radius) == "number" and isNotNull(params_.shoulderOffset) )
    ---@type number
    self.height = params_.height
    ---@type number
    self.radius = params_.radius
    ---@type number
    self.radius = params_.radius
    ---@type Vector3
    self.shoulderOffset = params_.shoulderOffset

end



function VCam3rdPersonFollowParams:__delete()
end





---@param a_ table @ { height : number, radius : number }
function VCam3rdPersonFollowParams:CopyParamsFrom( a_ )
    self.height = a_.height
    self.radius = a_.radius
    self.shoulderOffset = a_.shoulderOffset
end


---@param a_ VCam3rdPersonFollowParams
---@param b_ VCam3rdPersonFollowParams
---@param t_ number
function VCam3rdPersonFollowParams:Lerp( a_, b_, t_ )
    self.height = Mathf.Lerp( a_.height, b_.height, t_ )
    self.radius = Mathf.Lerp( a_.radius, b_.radius, t_ )
    self.shoulderOffset = Vector3.Lerp( a_.shoulderOffset, b_.shoulderOffset, t_ )
end



return VCam3rdPersonFollowParams
